function factorial(n: number): number {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}
console.log(factorial(5));

function fibonacci(n: number, memo: Record<number, number> = {}): number {
    if (n in memo) return memo[n];
    if (n <= 1) return n;
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo);
    return memo[n];
}

function once<T extends (...args: any[]) => any>(fn: T): T {
    let called: boolean = false;
    let result: ReturnType<T>;
    return ((...args: any[]) => {
        if (!called) {
            result = fn(...args);
            called = true;
        }
        return result;
    }) as T;
}

function retry<T>(fn: () => Promise<T>, maxAttempts: number = 3): Promise<T> {
    return new Promise(async (resolve, reject) => {
        for (let i = 0; i < maxAttempts; i++) {
            try {
                const result = await fn();
                resolve(result);
                return;
            } catch (err) {
                if (i === maxAttempts - 1) reject(err);
            }
        }
    });
}

function partial<T extends (...args: any[]) => any>(fn: T, ...presetArgs: any[]): (...args: any[]) => ReturnType<T> {
    return (...laterArgs: any[]) => fn(...presetArgs, ...laterArgs);
}
const add = (a: number, b: number, c: number): number => a + b + c;
const add5 = partial(add, 5);
